# typed: false
# frozen_string_literal: true

# Homebrew formula for the Engra CLI. Generated by packaging/release.py in the
# release workflow; do not hand-edit. Release assets live in
# arenberg-engineering/engra-releases.
class Engra < Formula
  desc "AI coding agent and developer assistant for the terminal"
  homepage "https://engra.io"
  # Proprietary software of Arenberg AG, all rights reserved (LICENSE.txt).
  license :cannot_represent

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.0/engra-0.4.0-macos-arm64.tar.gz"
      sha256 "b6cf6ca2660b78b51c1dfe0262b38f0245f185fd63c94d2b439e6ee565d51e8f"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.0/engra-0.4.0-macos-x64.tar.gz"
      sha256 "2716301d204e8d8393b323cb3095f986cafa40b67f665fcc9a40be3b180cc703"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.0/engra-0.4.0-linux-arm64.tar.gz"
      sha256 "aee38a2d09012f8b07fa2a51e3317e481499699d31bc0bfebcdd791ca377db83"
    end
    on_intel do
      url "https://github.com/arenberg-engineering/engra-releases/releases/download/v0.4.0/engra-0.4.0-linux-x64.tar.gz"
      sha256 "701f5c252cb96b1b0db4d3c90be521462f624014d2c9d7694265c2af52377a58"
    end
  end

  def install
    libexec.install "engra", "_internal"
    bin.install_symlink libexec/"engra"
    prefix.install "LICENSE.txt", "TERMS.md", "THIRD_PARTY_NOTICES.txt"
  end

  def caveats
    <<~EOS
      Sign in with:
        engra login

      Terms of Use: engra legal --terms

      Before uninstalling, run `engra logout` to remove saved credentials from
      the OS keychain. Settings and link state stay in ~/.config/engra (and
      doctor records in ~/.engra); remove them to clear everything.
    EOS
  end

  test do
    assert_equal "engra #{version}", shell_output("#{bin}/engra --version").strip
    assert_match "doctor", shell_output("#{bin}/engra --help")
    assert_match "Arenberg AG", shell_output("#{bin}/engra legal")
  end
end
